-- Inspection and Acceptance Report (IAR) Module — INFRASTRUCTURE tab (Statement of Work Accomplishments, SWA).
--   fims.statement_work_accomplishments   one row per approved Infrastructure RFA that has NO purchase order: the SWA number
--                                         (generated by the app: SWA-YYYY-MM-0001, unique), the RFA it was recorded for (allocation_id),
--                                         the Contract typed by the user, the dates (started / completion (revised) / contract duration)
--                                         and line_transaction (the work items, the account entries and the pro-forma JEV link).
-- Nothing that the RFA already knows is kept here: the RFA number, project code / name, program, contractor, location and the cost figures
-- (original contract cost, variation order, revised contract cost) are read live through allocation_id (RFA -> project / program / vendor /
-- budget request / budget line items), like the IAR reads its PO and supplier, so they are always accurate.
-- The RFA is picked from the Budget Allocation by the app (approved, Infrastructure category, empty po_number, no active DV).
--
-- line_transaction (array, ONE element — same shape as a delivery receipt in the IAR module's line_transaction):
--   [ { "items": [ { "description": "Excavation", "cost": "500000.00", "accomplishment_pct": "35.00" } ],
--       "lines": [ { "account_code": "1-04-03-020", "account_title": "Work-in-Process Inventory", "amount": "4500000.00" } ],   -- the account entries
--       "jev_id": 12, "jev_no": "JEV-26-11-0004" } ]                                                                              -- set when the pro-forma is submitted
--   items: description is required, cost >= 0, accomplishment_pct is the item's share of the project (0 to 100 each, 100 at most in total);
--   the items' total cost may not exceed the lines' total, and the lines' total may not exceed the RFA amount (all checked by the app).

-- A database that has an earlier version of this table is migrated here (a fresh database skips it):
--   * iar_number becomes swa_number; the project details, project_cost, the cost figures, account_entries and jev_id / jev_no columns are dropped;
--   * line_transaction (the plain array of work items) becomes [ { items, lines, jev_id, jev_no } ], carrying the dropped account_entries / jev_id / jev_no over.
DO $$
BEGIN
    IF to_regclass('fims.statement_work_accomplishments') IS NOT NULL THEN
        IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'fims' AND table_name = 'statement_work_accomplishments' AND column_name = 'iar_number') THEN
            ALTER TABLE fims.statement_work_accomplishments RENAME COLUMN iar_number TO swa_number;
        END IF;
        IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'uq_swa_iar_number' AND conrelid = 'fims.statement_work_accomplishments'::regclass) THEN
            ALTER TABLE fims.statement_work_accomplishments RENAME CONSTRAINT uq_swa_iar_number TO uq_swa_swa_number;
        END IF;
        IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'fims' AND table_name = 'statement_work_accomplishments' AND column_name = 'account_entries') THEN
            EXECUTE $q$
                UPDATE fims.statement_work_accomplishments
                   SET line_transaction = jsonb_build_array(jsonb_build_object(
                           'items', line_transaction, 'lines', COALESCE(account_entries, '[]'::jsonb), 'jev_id', jev_id, 'jev_no', jev_no))
                 WHERE jsonb_typeof(line_transaction) = 'array' AND (jsonb_array_length(line_transaction) = 0 OR line_transaction -> 0 ? 'description')
            $q$;
        END IF;
        ALTER TABLE fims.statement_work_accomplishments
            DROP COLUMN IF EXISTS rfa_number, DROP COLUMN IF EXISTS project_code, DROP COLUMN IF EXISTS project_name, DROP COLUMN IF EXISTS location,
            DROP COLUMN IF EXISTS program_code, DROP COLUMN IF EXISTS program_name, DROP COLUMN IF EXISTS vendor_id, DROP COLUMN IF EXISTS contractor,
            DROP COLUMN IF EXISTS project_cost, DROP COLUMN IF EXISTS contract_cost, DROP COLUMN IF EXISTS original_contract_cost, DROP COLUMN IF EXISTS variation_order,
            DROP COLUMN IF EXISTS account_entries, DROP COLUMN IF EXISTS jev_id, DROP COLUMN IF EXISTS jev_no;
    END IF;
END $$;

CREATE TABLE IF NOT EXISTS fims.statement_work_accomplishments (
    swa_id                   SERIAL PRIMARY KEY,
    swa_number               VARCHAR(50)   NOT NULL,            -- generated by the app: SWA-YYYY-MM-0001 (unique)
    allocation_id            INTEGER       NOT NULL,            -- the approved RFA (fims.budget_allocation.allocation_id)
    contract                 VARCHAR(255),                      -- typed by the user
    date_started             DATE,
    completion_date_revised  DATE,
    contract_duration        VARCHAR(100),                      -- e.g. "180 calendar days"
    line_transaction         JSONB         NOT NULL DEFAULT '[]'::jsonb,   -- [ { items[], lines[] (account entries), jev_id, jev_no } ]
    created_by               INTEGER,
    created_at               TIMESTAMPTZ   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by               INTEGER,
    updated_at               TIMESTAMPTZ,
    CONSTRAINT uq_swa_swa_number     UNIQUE (swa_number),
    CONSTRAINT uq_swa_allocation_id  UNIQUE (allocation_id),
    CONSTRAINT fk_swa_allocation     FOREIGN KEY (allocation_id) REFERENCES fims.budget_allocation (allocation_id) ON DELETE RESTRICT,
    CONSTRAINT chk_swa_lines_array   CHECK (jsonb_typeof(line_transaction) = 'array')
);
COMMENT ON TABLE  fims.statement_work_accomplishments IS 'Infrastructure SWA: one row per approved Infrastructure RFA without a PO — the contract, dates and line_transaction (work items, account entries, pro-forma JEV link); everything else is read live from the RFA (allocation_id)';
COMMENT ON COLUMN fims.statement_work_accomplishments.swa_number IS 'SWA number, generated: SWA-YYYY-MM-0001';
COMMENT ON COLUMN fims.statement_work_accomplishments.contract IS 'Contract: typed by the user';
COMMENT ON COLUMN fims.statement_work_accomplishments.line_transaction IS 'One element: {items: Statement of Work Accomplishments [{description, cost, accomplishment_pct}], lines: account entries [{account_code, account_title, amount}], jev_id, jev_no: the pro-forma JEV}';

-- A database that has the table from an earlier version of this file gets the column added here (a fresh one already has it).
ALTER TABLE fims.statement_work_accomplishments ADD COLUMN IF NOT EXISTS contract VARCHAR(255);
